const TARGETS = ['D00021','D00664','D01709','D01774','D02484','D02511','D02527'];
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

function s(v) { return String(v == null ? '' : v).trim(); }
const out = [];
for (const t of TARGETS) {
  const h = rows.filter(function (r) { return s(r.deal_id) === t; })[0];
  if (!h) { out.push({ json: { deal_id: t, ERROR: 'not found' } }); continue; }
  out.push({ json: {
    deal_id: t,
    investor: s(h.investor),
    startup: s(h.startup),
    investor_response: s(h.investor_response) || '(none)',
    pass_reason: s(h.pass_reason) || '',
    meeting_scheduled: s(h.meeting_scheduled) || '',
    meeting_date: s(h.meeting_date) || '',
    meetings_held: s(h.meetings_held) || '',
    meeting_outcome: s(h.meeting_outcome) || '',
    committed_cr: s(h.committed_cr) || '',
    deal_status: s(h.deal_status) || '',
    date_shared: s(h.date_shared),
    last_contact: s(h.last_contact),
    fu1: s(h.fu1_done) + (s(h.fu1_date) ? ' ' + s(h.fu1_date) : ''),
    fu2: s(h.fu2_done) + (s(h.fu2_date) ? ' ' + s(h.fu2_date) : ''),
    fu3: s(h.fu3_done) + (s(h.fu3_date) ? ' ' + s(h.fu3_date) : ''),
    next_action: s(h.next_action),
    next_due: s(h.next_due),
    has_thread: s(h.thread_id) ? 'yes' : 'no'
  }});
}
return out;
